begin;
select plan(17);
select has_column('public','retention_schedule','facility_id','retention rules are facility scoped');
select has_column('public','retention_schedule','version','retention schedule edits retain version metadata');
select has_table('public','record_archive_registry','records have an explicit archive or seal state');
select has_table('public','disposal_certificates','completed disposal retains an immutable certificate');
select has_column('public','legal_holds','case_reference','legal holds retain case references');
select has_column('public','retention_action_requests','second_approved_by','disposal records its second approver');
select has_function('public','configure_retention_schedule',array['uuid','text','integer','text'],'retention durations and legal basis are configured explicitly');
select has_function('public','place_legal_hold_case',array['uuid','uuid','text','text','text','text'],'legal holds are captured as scoped cases');
select has_function('public','approve_retention_disposal',array['uuid','boolean','text'],'disposal requires a second approval');
select has_function('public','execute_retention_action',array['uuid'],'approved actions archive or seal and issue a certificate');
select has_trigger('public','disposal_certificates','disposal_certificates_immutable','disposal certificates cannot be edited or deleted');
select has_trigger('public','patients','retention_hard_delete_block','patient hard deletes are blocked');
select has_trigger('public','encounters','retention_hard_delete_block','encounter hard deletes are blocked');
select ok((select is_nullable='YES' from information_schema.columns where table_schema='public' and table_name='retention_schedule' and column_name='retention_days'),'schedule duration has no default and may remain unset pending review');
select ok(exists(select 1 from pg_constraint where conrelid='public.disposal_certificates'::regclass and contype='c' and pg_get_constraintdef(oid) like '%first_approved_by%second_approved_by%'),'certificate enforces two distinct approvers');
select ok((select count(*)=0 from public.retention_schedule where retention_days is null and approved),'an unset duration cannot be used by an approved schedule');
select ok(position('sealed_source_retained' in (select column_default from information_schema.columns where table_schema='public' and table_name='disposal_certificates' and column_name='disposition_method'))>0,'disposal seals source records rather than deleting linked clinical data');
select * from finish();
rollback;
